import {createFacilityMap} from './facility-map.js';
import {languages,normalizeLanguage,translate,localize} from './language.js';
import {facilities,wards,photoUrl,dimensions,statusLabels,score,filterFacilities,initialComplaints} from './data.js';
let facilityMap;
const $=s=>document.querySelector(s), main=$('#main'), dialog=$('#detail');
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
function read(key,fallback){try{return JSON.parse(localStorage.getItem(key))??fallback}catch{return fallback}}
let language=normalizeLanguage(read('js-language-v1','en'));
const refreshLanguage=()=>{document.documentElement.lang=language;localize(document.body,language)};
const currentRecords=items=>Array.isArray(items)?items.filter(item=>facilities.some(f=>f.id===item.facility)):[];
let complaints=currentRecords(read('js-complaints-v1',initialComplaints)),assessments=currentRecords(read('js-assessments-v1',[])),ratings=currentRecords(read('js-ratings-v1',[]));
function save(key,data){try{localStorage.setItem(key,JSON.stringify(data));return true}catch{toast('Storage is unavailable. This change lasts only for this session.');return false}}
function toast(message){$('#toast').textContent=message;refreshLanguage();$('#toast').style.display='block';setTimeout(()=>$('#toast').style.display='none',4200)}
const date=s=>s?`<time datetime="${esc(s)}">${new Date(s).toLocaleDateString(`${language}-IN`,{day:'numeric',month:'short',year:'numeric'})}</time>`:'Not assessed';
const badge=f=>`<span class="badge ${f.status}">${statusLabels[f.status]}</span>`;
const options=(items,current)=>items.map(x=>`<option ${x===current?'selected':''}>${esc(x)}</option>`).join('');
const facilityOptions=id=>facilities.map(f=>`<option value="${f.id}" ${id===f.id?'selected':''}>${esc(f.name)}</option>`).join('');
function intro(kicker,title,description,action=''){return `<section class="intro"><div><div class="eyebrow">${kicker}</div><h1>${title}</h1><p>${description}</p></div>${action}</section>`}
function stats(items){return `<div class="stats">${items.map(([label,value,note,color=''])=>`<div class="stat"><span class="dot ${color}"></span><div class="label">${label}</div><strong>${value}</strong><small>${note}</small></div>`).join('')}</div>`}
function mapPage(){main.innerHTML=intro('YOUR NEIGHBOURHOOD, BETTER UNDERSTOOD','Find a place that works for you.','Explore civic amenities, see verified conditions, and help your community.',`<a class="button primary" href="#complaints/new">＋ Report a problem</a>`)+stats([['Listed amenities',facilities.length,'Thane dataset'],['Verified usable',facilities.filter(f=>f.status==='usable').length,'Based on field status'],['Needs attention',facilities.filter(f=>['partial','unusable'].includes(f.status)).length,'Partly usable or not usable','amber'],['Awaiting verification',facilities.filter(f=>f.status==='unverified').length,'Field assessment pending','grey']])+`<div class="toolbar"><input class="search" id="search" aria-label="Search facilities or wards" placeholder="⌕  Search an amenity or ward…"><select id="ward" aria-label="Ward">${options(['All wards',...wards])}</select><label class="button"><input id="usable" type="checkbox"> Usable only</label><label class="button"><input id="accessible" type="checkbox"> Step-free access</label></div><div class="chips" aria-label="Amenity types">${['All amenities',...new Set(facilities.map(f=>f.type))].map((t,i)=>`<button class="chip ${i?'':'selected'}" data-type="${t}" aria-pressed="${!i}">${t}</button>`).join('')}</div><div class="explorer"><section class="street-map-panel"><div class="map-actions"><strong>Thane street map</strong><button class="button" id="city-view">Entire Thane</button><button class="button" id="facility-view">Show facilities</button></div><div class="map street-map" id="thane-map" aria-label="Interactive street map of Thane" translate="no"></div><p class="note" id="map-message" role="status">Loading street map. Internet is required for roads and buildings.</p><div class="map-legend"><span><i class="dot"></i>Usable</span><span><i class="dot amber"></i>Partly usable</span><span><i class="dot red"></i>Not usable</span><span><i class="dot grey"></i>Unverified</span></div></section><section><div class="list-head"><h2>Explore amenities</h2><span id="count"></span></div><div class="facility-list" id="facilities"></div></section></div><div class="callout"><div><h3>A listing is only the beginning.</h3><p>Field assessments show whether a facility is actually accessible, available and usable.</p></div><a class="button" href="#analytics">Explore the index ↗</a></div>`;
facilityMap=createFacilityMap($('#thane-map'),$('#map-message'),facilityDetail);$('#city-view').onclick=()=>facilityMap.cityView();$('#facility-view').onclick=()=>facilityMap.showFacilities();
let type='All amenities';function update(){const found=filterFacilities({query:'',ward:$('#ward').value,type,usable:$('#usable').checked,accessible:$('#accessible').checked}).filter(f=>`${f.name} ${f.ward??''} ${f.locality} ${f.facility_id} ${translate(f.name,language)} ${translate(f.ward??'',language)}`.toLocaleLowerCase().includes($('#search').value.toLocaleLowerCase()));$('#count').textContent=`${found.length} facilities`;$('#facilities').innerHTML=found.map(f=>`<button class="facility" data-facility="${f.id}"><div class="facility-top"><div><h3>${esc(f.name)}</h3><p>${esc(f.type)} · ${esc(f.ward??'Ward unknown')}</p></div><span class="score" aria-label="Illustrative CAAUI score">${score(f.scores)??'—'}</span></div>${badge(f)}<span class="verified">${f.verified?date(f.verified):'Not yet verified'}</span></button>`).join('')||'<div class="empty">No matching amenities.<br>Try another filter or search.</div>';facilityMap.update(found);main.querySelectorAll('[data-facility]').forEach(b=>b.onclick=()=>{facilityMap.focus(b.dataset.facility);facilityDetail(b.dataset.facility)});refreshLanguage()}main.querySelectorAll('input,select').forEach(e=>e.addEventListener('input',update));main.querySelectorAll('[data-type]').forEach(b=>b.onclick=()=>{type=b.dataset.type;main.querySelectorAll('[data-type]').forEach(c=>{c.classList.toggle('selected',c===b);c.setAttribute('aria-pressed',c===b)});update()});update();}
function show(content){$('#detail-content').innerHTML=`<button class="close" aria-label="Close dialog">×</button>${content}`;$('.close').onclick=()=>dialog.close();refreshLanguage();dialog.showModal()}
function facilityDetail(id){const f=facilities.find(f=>f.id===id);if(!f)return;show(`<div class="eyebrow">${esc(f.type)} · ${esc(f.ward??'Ward unknown')}</div><h1>${esc(f.name)}</h1>${badge(f)}<div class="detail-grid"><div><small>Source record</small><strong>Photo-documented · not independently verified</strong></div><div><small>Field status</small><strong>${statusLabels[f.status]}</strong></div><div><small>Last field assessment</small><strong>${date(f.verified)}</strong></div><div><small>Opening hours</small><strong>${esc(f.hours??'Unknown')}</strong></div></div>${f.verified&&(Date.now()-Date.parse(f.verified)>90*86400000)?'<p class="warning">Assessment is over 90 days old and may be outdated.</p>':''}<h2>Illustrative CAAUI: ${score(f.scores)??'Insufficient data'}</h2><p class="note">Scores require a field assessment. Missing dimensions are excluded; these are not validated research scores.</p>${dimensions.map((d,i)=>`<div class="bar-row"><span>${d}</span><div class="bar"><i style="width:${f.scores[i]??0}%"></i></div><span>${f.scores[i]??'—'}</span></div>`).join('')}<h2>Facility photos</h2><p class="note">PDF page renders; observations are not verified service conditions.</p><div class="facility-photos">${[f.cover_photo_path,...f.photos.filter(p=>p!==f.cover_photo_path)].filter(Boolean).map((p,i)=>`<a href="${esc(photoUrl(p))}" target="_blank" rel="noopener"><img loading="lazy" src="${esc(photoUrl(p))}" alt="${esc(f.name)} — ${p===f.geotag_photo_path?'Location evidence':'Photo '+(i+1)}"></a>`).join('')}</div><p><strong>Facility ID:</strong> ${esc(f.facility_id)}</p><p><strong>Location:</strong> ${esc(f.locality)} · ${esc(f.latitude??'Unknown')}, ${esc(f.longitude??'Unknown')} (${esc(f.location_confirmed==='yes'?'confirmed':'unconfirmed')})</p><p><strong>Source:</strong> ${esc(f.source_pdf)} · page ${esc(f.geotag_source_page)}</p><p><strong>Photo timestamp:</strong> ${esc(f.geotag_captured_at||'Unknown')} (not an assessment date)</p><p><strong>Printed address:</strong> ${esc(f.address_from_stamp)}</p><p><strong>Photo observations:</strong> ${esc(f.photo_observations)}</p><p class="note"><strong>Review notes:</strong> ${esc(f.review_notes)}</p><a class="button primary" id="report-link" href="#complaints/new/${id}">Report a problem</a><hr><form id="rating-form"><h3>Share quick feedback</h3><label>Your rating<select name="rating">${options(['5','4','3','2','1'])}</select></label><label>Feedback<textarea name="feedback" maxlength="500" required></textarea></label><button class="button">Save demo feedback</button></form>`);$('#report-link').onclick=()=>dialog.close();$('#rating-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);ratings.push({facility:id,rating:Number(d.get('rating')),feedback:d.get('feedback'),at:new Date().toISOString()});save('js-ratings-v1',ratings);dialog.close();toast('Feedback saved locally. Verified facility status stays unchanged.')};}
function complaintPage(newId){main.innerHTML=intro('CITIZEN REPORTS','A small report. A better public place.','Track demo reports and help close the loop on civic issues.',`<a href="#complaints/new" class="button primary">＋ New complaint</a>`)+`<p class="note">Demo reports stay in this browser. They are not sent to any government department.</p>`+(newId!==undefined?`<section class="panel"><h2>Report a problem</h2><p>Select a facility and tell us what needs attention.</p><form id="complaint-form"><div class="two-col"><label>Facility<select name="facility">${facilityOptions(newId)}</select></label><label>Issue category<select name="category">${options(['Not working','No water','Unclean','Unsafe','Locked / inaccessible','Overcharging','Damaged','Other'])}</select></label></div><label>What happened?<textarea name="description" required minlength="10" maxlength="1500" placeholder="Describe the issue (at least 10 characters)"></textarea></label><div class="form-actions"><button class="button primary">Submit demo complaint</button><a href="#complaints" class="button">Cancel</a></div><span class="support">Photo upload, GPS capture and OTP verification will be connected in a later build.</span></form></section>`:'')+`<section class="panel"><h2>Your demo complaints</h2>${complaintTable(complaints,false)}</section>`;if($('#complaint-form'))$('#complaint-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),now=new Date().toISOString(),c={id:'JS-'+crypto.randomUUID().slice(0,8).toUpperCase(),facility:d.get('facility'),category:d.get('category'),description:String(d.get('description')).trim(),created:now,status:'Submitted',priority:'Normal',assignee:'Unassigned',events:[{status:'Submitted',at:now,reason:'Citizen demo report'}]};if(c.description.length<10){toast('Please enter at least 10 non-space characters.');return}complaints.unshift(c);save('js-complaints-v1',complaints);location.hash='complaints';toast(`Demo complaint ${c.id} saved.`)};bindComplaints(false);}
function complaintTable(items,staff){return `<div class="table-wrap"><table><thead><tr><th>COMPLAINT</th><th>FACILITY / ISSUE</th><th>STATUS</th><th>${staff?'PRIORITY':'SUBMITTED'}</th><th></th></tr></thead><tbody>${items.map(c=>`<tr><td>${esc(c.id)}</td><td>${esc(facilities.find(f=>f.id===c.facility)?.name)}<br><small class="support">${esc(c.category)}</small></td><td><span class="badge">${esc(c.status)}</span></td><td>${staff?esc(c.priority):date(c.created)}</td><td><button class="button" data-complaint="${esc(c.id)}">${staff?'Manage':'View'}</button></td></tr>`).join('')}</tbody></table>${items.length?'':'<div class="empty">No complaints match this view.</div>'}</div>`}
function bindComplaints(staff){main.querySelectorAll('[data-complaint]').forEach(b=>b.onclick=()=>complaintDetail(b.dataset.complaint,staff))}
function complaintDetail(id,staff){const c=complaints.find(c=>c.id===id);show(`<div class="eyebrow">${esc(c.id)}</div><h1>${esc(c.category)}</h1><p translate="no">${esc(c.description)}</p><p class="note"><span translate="no">${esc(c.assignee)}</span> · ${esc(c.priority)}</p>${c.events.map(e=>`<div class="audit"><strong>${esc(e.status)}</strong><small>${date(e.at)} · <span translate="no">${esc(e.reason)}</span></small></div>`).join('')}${staff?`<form id="status-form"><label>Assign to<input name="assignee" value="${esc(c.assignee)}" required maxlength="80"></label><label>Priority<select name="priority">${options(['Normal','High','Urgent'],c.priority)}</select></label><label>Status<select name="status">${options(['Submitted','Acknowledged','Assigned','In progress','Resolved','Closed','Rejected'],c.status)}</select></label><label>Remarks<textarea name="reason" required maxlength="500"></textarea></label><p class="note">Resolution is disabled until evidence uploads are connected. This demo portal has no role authentication.</p><button class="button primary">Save demo update</button></form>`:c.status==='Resolved'?'<div class="form-actions"><button class="button primary" id="confirm">Confirm resolution</button><button class="button" id="dispute">Dispute and reopen</button></div>':'<p class="note">You can confirm or dispute a resolution when it is marked resolved.</p>'}`);if(staff)$('#status-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target),status=d.get('status');if(status==='Resolved'){toast('Resolution requires photo evidence; upload support is not connected yet.');return}if(status==='Closed'&&c.status!=='Resolved'){toast('A complaint must be resolved with evidence before it can be closed.');return}if(!String(d.get('reason')).trim()){toast('Please add a reason for this change.');return}c.status=status;c.priority=d.get('priority');c.assignee=String(d.get('assignee')).trim();c.events.push({status,at:new Date().toISOString(),reason:d.get('reason')});save('js-complaints-v1',complaints);dialog.close();render();toast('Demo update saved to the local activity log.')};if($('#confirm'))$('#confirm').onclick=()=>citizenDecision(c,'Closed','Citizen confirmed resolution');if($('#dispute'))$('#dispute').onclick=()=>citizenDecision(c,'In progress','Citizen disputed resolution');}
function citizenDecision(c,status,reason){c.status=status;c.events.push({status,reason,at:new Date().toISOString()});save('js-complaints-v1',complaints);dialog.close();render();}
function government(){main.innerHTML=intro('OFFICIAL WORKSPACE · DEMO','Turn reports into action.','Review the sample inbox, assign ownership and record progress.')+`<p class="note">Staff workflow preview only. Production access will require authenticated roles and server-side permissions.</p>`+stats([['Open reports',complaints.filter(c=>!['Closed','Resolved','Rejected'].includes(c.status)).length,'Locally stored demo records'],['Unassigned',complaints.filter(c=>c.assignee==='Unassigned').length,'Awaiting a team','amber'],['In progress',complaints.filter(c=>c.status==='In progress').length,'Work underway'],['Resolved',complaints.filter(c=>c.status==='Resolved').length,'Evidence required']])+`<div class="toolbar"><select id="inbox-status" aria-label="Filter by complaint status">${options(['All statuses','Submitted','Acknowledged','Assigned','In progress','Resolved','Closed','Rejected'])}</select></div><section class="panel"><h2>Complaint inbox</h2><div id="inbox"></div></section>`;const update=()=>{$('#inbox').innerHTML=complaintTable(complaints.filter(c=>$('#inbox-status').value==='All statuses'||c.status===$('#inbox-status').value),true);bindComplaints(true);refreshLanguage()};$('#inbox-status').onchange=update;update();}
function analytics(){const scores=facilities.map(f=>score(f.scores)).filter(x=>x!==null);main.innerHTML=intro('EVIDENCE FOR BETTER DECISIONS','Look beyond the number of facilities.','Review Thane facility coverage and verification gaps.',`<button class="button" id="export">↓ Export facility CSV</button>`)+stats([['Illustrative mean CAAUI',score(scores)??'Insufficient data','No scores without assessments'],['Field assessed',facilities.filter(f=>f.verified).length+' / '+facilities.length,'Verified assessment dates only'],['Fully usable',facilities.filter(f=>f.status==='usable').length+' / '+facilities.length,'Unknown is not unusable'],['Local complaints',complaints.length,'Includes your demo reports','amber']])+`<div class="two-col"><section class="panel"><h2>Facility score comparison</h2><p>CAAUI · 0–100 · illustrative equal weights</p>${facilities.map(f=>`<div class="bar-row"><span>${esc(f.name)}</span><div class="bar"><i style="width:${score(f.scores)??0}%"></i></div><strong>${score(f.scores)??'—'}</strong></div>`).join('')}</section><section class="panel"><h2>Provision–usability gap</h2><p>Imported listings compared with verified usable facilities.</p><div class="table-wrap"><table><thead><tr><th>WARD</th><th>LISTED</th><th>USABLE</th><th>PARTLY</th></tr></thead><tbody>${wards.map(w=>{const fs=facilities.filter(f=>(f.ward??'Ward unknown')===w);return `<tr><td>${esc(w)}</td><td>${fs.length}</td><td>${fs.filter(f=>f.status==='usable').length}</td><td>${fs.filter(f=>f.status==='partial').length}</td></tr>`}).join('')}</tbody></table></div><h3 style="margin-top:28px">Where to start</h3><p>Confirm entrance locations, wards and service conditions on site before assigning scores. Photo timestamps are not assessment dates.</p><p class="note">Ward coverage-adjusted scores need population and geographic data. They are not calculated in this skeleton.</p></section></div><section class="panel"><h2>A transparent starting point</h2><p>Each available dimension contributes equally to the demo facility score. Missing values are excluded, never scored as zero. Research weights, normalisation, score version history and regional coverage metrics remain to be defined.</p></section>`;$('#export').onclick=()=>{const rows=[['facility_id','facility','ward','type','field_status','last_verified','illustrative_caaui'],...facilities.map(f=>[f.id,f.name,f.ward,f.type,f.status,f.verified??'',score(f.scores)??''])];const csv=rows.map(r=>r.map(c=>'"'+String(c).replaceAll('"','""')+'"').join(',')).join('\r\n');const a=document.createElement('a');a.href=URL.createObjectURL(new Blob([csv],{type:'text/csv;charset=utf-8'}));a.download='jansuvidha-thane-facilities.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000)};}
function assessment(){main.innerHTML=intro('FIELDWORK','Better evidence starts on the ground.','A structured assessment form for the first survey workflow.')+`<div class="two-col"><section class="panel"><h2>Save an assessment draft</h2><p>Drafts stay on this device and do not change verified facility status.</p><form id="assessment-form"><label>Facility<select name="facility">${facilityOptions()}</select></label><label>Assessment date<input name="date" type="date" value="${new Date().toISOString().slice(0,10)}" required></label><label>Observed condition<select name="condition">${options(['Usable','Partly usable','Not usable','Unable to assess'])}</select></label><div class="checks"><label><input type="checkbox" name="water"> Water available</label><label><input type="checkbox" name="accessible"> Step-free access</label><label><input type="checkbox" name="clean"> Clean</label></div><label>Field notes<textarea name="notes" required maxlength="1500"></textarea></label><button class="button primary">Save local draft</button><span class="support">GPS, timestamped photos and surveyor verification are required before a draft can become field evidence.</span></form></section><section class="panel"><h2>Assessment drafts</h2><div id="drafts"></div></section></div>`;function update(){$('#drafts').innerHTML=assessments.length?assessments.map(a=>`<div class="audit"><strong>${esc(facilities.find(f=>f.id===a.facility)?.name)}</strong><small>${esc(a.date)} · ${esc(a.condition)} · Draft only</small><p translate="no">${esc(a.notes)}</p></div>`).join(''):'<div class="empty">No drafts yet.<br>Your first fieldwork starts here.</div>';refreshLanguage()}update();$('#assessment-form').onsubmit=e=>{e.preventDefault();const d=new FormData(e.target);if(!String(d.get('notes')).trim()){toast('Please add field notes.');return}assessments.unshift({...Object.fromEntries(d),created:new Date().toISOString()});save('js-assessments-v1',assessments);update();toast('Assessment draft saved locally.');};}
function render(){facilityMap?.destroy();facilityMap=null;const [page='map',action,id]=location.hash.slice(1).split('/');const names={map:'Suvidha Map',complaints:'My complaints',government:'Government portal',analytics:'Analytics',assessment:'Field assessment'};$('#breadcrumb').textContent=names[page]??names.map;document.querySelectorAll('nav a').forEach(a=>{const active=a.hash==='#'+page;a.classList.toggle('active',active);if(active)a.setAttribute('aria-current','page');else a.removeAttribute('aria-current')});if(page==='complaints')complaintPage(action==='new'?(id??''):undefined);else if(page==='government')government();else if(page==='analytics')analytics();else if(page==='assessment')assessment();else mapPage();refreshLanguage();}
const languageSelect=$('#language');
const themeSelect=$('#theme');
themeSelect.value=document.documentElement.dataset.theme;
themeSelect.onchange=()=>{
  document.documentElement.dataset.theme=themeSelect.value;
  save('js-theme-v1',themeSelect.value);
};
languageSelect.innerHTML=Object.entries(languages).map(([code,label])=>`<option value="${code}" lang="${code}">${label}</option>`).join('');
languageSelect.value=language;
languageSelect.onchange=()=>{language=normalizeLanguage(languageSelect.value);save('js-language-v1',language);refreshLanguage()};
window.addEventListener('hashchange',render);render();
